import sys
from bisect import bisect_right

def int_iter():
    data = sys.stdin.buffer.read()
    num = 0
    in_num = False
    for c in data:
        if 48 <= c <= 57:
            num = num * 10 + (c - 48)
            in_num = True
        else:
            if in_num:
                yield num
                num = 0
                in_num = False
    if in_num:
        yield num

def solve():
    it = int_iter()
    try:
        n = next(it)
    except StopIteration:
        return

    X = [0] * n
    for i in range(n):
        X[i] = next(it)

    H = [0] * n
    for i in range(n):
        H[i] = next(it)
    del it

    ans = [0] * n
    stack = []
    br = bisect_right

    for i in range(n - 1, -1, -1):
        end = br(X, X[i] + H[i]) - 1
        while stack and stack[-1][0] <= end:
            if stack[-1][1] > end:
                end = stack[-1][1]
            stack.pop()
        ans[i] = end - i + 1
        stack.append((i, end))

    sys.stdout.write(" ".join(map(str, ans)))

if __name__ == "__main__":
    solve()
